SELECT bno, title, content, writer, regdate, replycnt
FROM (
    SELECT rownum rn, bno, title, content, writer, regdate, replycnt
    FROM (
        SELECT bno, title, content, writer, regdate, replycnt
        FROM tbl_board
        ORDER BY bno DESC
    )
    WHERE rownum <= #{pageNum} * #{amount}
)
WHERE rn > (#{pageNum} - 1) * #{amount}

